state.trial=async function(rendererName,shadowMultiplier=1){
 if(state.status!=='ready')throw new Error('No qualified frame or trial already active');
 state.status='measuring';
 const renderer=rendererName==='baseline'?baseline:current;
 const descriptor=Object.getOwnPropertyDescriptor(CanvasRenderingContext2D.prototype,'shadowBlur');
 const durations=[],intervals=[];let previous;
 if(shadowMultiplier!==1)Object.defineProperty(CanvasRenderingContext2D.prototype,'shadowBlur',{...descriptor,set(value){descriptor.set.call(this,value*shadowMultiplier)}});
 try{
  for(let index=0;index<33;index++){
   const now=await new Promise(done=>requestAnimationFrame(done));
   const began=performance.now();renderer(ctx,state.frame,1280,720,state.renderZoom,0,0);
   if(index>=3){durations.push(performance.now()-began);if(previous!==undefined)intervals.push(now-previous);}
   previous=now;
  }
  const sorted=[...intervals].sort((a,b)=>a-b);
  const sortedDurations=[...durations].sort((a,b)=>a-b);
  const report={renderer:rendererName,shadowMultiplier,renderZoom:state.renderZoom,geometry:state.geometry,frameSha256:state.frameSha256,samples:durations.length,intervalP95Ms:sorted[Math.ceil(sorted.length*.95)-1],fractionIntervalsAtMost40Ms:intervals.filter(x=>x<=40).length/intervals.length,durationP95Ms:sortedDurations[Math.ceil(sortedDurations.length*.95)-1],durationMeanMs:durations.reduce((a,b)=>a+b,0)/durations.length,visible:document.visibilityState,focus:document.hasFocus()};
  state.reports.push(report);return report;
 }finally{Object.defineProperty(CanvasRenderingContext2D.prototype,'shadowBlur',descriptor);state.status='ready';}
};
